def-hyp(
    list-partial(
        Type.judge(@f, Type.to(X@Topology.ctxt.X, Y@Topology.ctxt.Y)),
        Type.judge(@τ_X, Set(Set(X@Topology.ctxt.X))),
        Type.judge(@τ_Y, Set(Set(Y@Topology.ctxt.Y)))
    ),
    Topology.homeomorphism(f, X@Topology.ctxt.X, Y@Topology.ctxt.Y),
    Logic.and(Logic.and(Topology.continuousMap(f, X@Topology.ctxt.X, Y@Topology.ctxt.Y), Topology.openMap(f)), Set.bijective(f))
)
